"use client";

import React from 'react';
import { DashboardCard } from '@/components/client/DashboardCard';
import {
    Calendar,
    User,
    Scissors,
    Clock,
    ArrowRight,
    History,
    TicketPercent,
    Star,
    Sparkles,
    CalendarPlus
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import Link from 'next/link';
import { useBarber } from '@/context/BarberContext';

export default function ClientDashboard() {
    const { appointments, currentUser, promotions } = useBarber();

    // Get current client's appointments
    const clientAppointments = appointments.filter(a => a.clientId === currentUser?.id);
    const completedApps = clientAppointments.filter(a => a.status === 'concluido');

    // Get next appointment
    const nextApp = clientAppointments
        .filter(a => a.status === 'agendado' || a.status === 'confirmado')
        .sort((a, b) => new Date(`${a.date} ${a.time}`).getTime() - new Date(`${b.date} ${b.time}`).getTime())[0];

    return (
        <div className="space-y-10 animate-fade-in-up">
            {/* Quick Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <DashboardCard
                    title="Próximo Atendimento"
                    value={nextApp ? nextApp.date.split('-').reverse().join('/') : "--/--/----"}
                    subtitle={nextApp ? nextApp.time : "Nenhum agendado"}
                    icon={<Calendar className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Barbeiro"
                    value={nextApp ? nextApp.barberName : "---"}
                    subtitle={nextApp ? "Profissional Premium" : "Escolha um barbeiro"}
                    icon={<User className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Serviço"
                    value={nextApp ? nextApp.serviceName : "---"}
                    subtitle={nextApp ? `R$ ${nextApp.price.toFixed(2)}` : "Selecione um serviço"}
                    icon={<Scissors className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Total de Cortes"
                    value={completedApps.length.toString()}
                    subtitle="Estilo consolidado"
                    icon={<Sparkles className="w-6 h-6" />}
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 space-y-8">
                    {/* Welcome Banner */}
                    <div className="relative overflow-hidden bg-gradient-to-br from-[var(--color-dark-card)] to-black border border-[var(--color-dark-border)] rounded-3xl p-8 lg:p-10">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-[var(--color-primary-gold)]/5 rounded-full blur-3xl -mr-20 -mt-20" />
                        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                            <div>
                                <h3 className="text-3xl font-bold text-white mb-2 tracking-tight">
                                    Olá, {currentUser?.name.split(' ')[0]}! <br />
                                    Pronto para seu <span className="text-[var(--color-primary-gold)]">novo visual?</span>
                                </h3>
                                <p className="text-gray-400 mb-6 max-w-md">Garanta seu horário com os melhores profissionais. Sua satisfação é nossa prioridade absoluta.</p>
                                <Link href="/client/schedule">
                                    <Button size="lg" className="w-full md:w-auto h-14 px-10 gap-2 text-sm font-black tracking-widest bg-[var(--color-primary-gold)] shadow-[0_10px_30px_rgba(212,175,55,0.2)]">
                                        <CalendarPlus className="w-5 h-5" /> AGENDAR AGORA
                                    </Button>
                                </Link>
                            </div>
                        </div>
                    </div>

                    {/* Recent History Preview */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between px-2">
                            <h4 className="flex items-center gap-2 text-lg font-bold">
                                <History className="w-5 h-5 text-[var(--color-primary-gold)]" /> Histórico Recente
                            </h4>
                            <Link href="/client/history" className="text-xs text-[var(--color-primary-gold)] hover:underline flex items-center gap-1">Ver todos <ArrowRight className="w-3 h-3" /></Link>
                        </div>
                        <div className="space-y-3">
                            {completedApps.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between p-5 bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-2xl hover:bg-white/5 transition-all">
                                    <div className="flex items-center gap-4">
                                        <div className="text-center w-12 border-r border-[var(--color-dark-border)] pr-4">
                                            <p className="text-xs font-bold text-white">{item.date.split('-')[2]}</p>
                                            <p className="text-[10px] text-gray-500 uppercase tracking-tighter">
                                                {new Date(item.date).toLocaleDateString('pt-BR', { month: 'short' }).toUpperCase()}
                                            </p>
                                        </div>
                                        <div>
                                            <p className="font-bold text-sm text-white">{item.serviceName}</p>
                                            <p className="text-[10px] text-gray-500 font-medium">Barbeiro: {item.barberName}</p>
                                        </div>
                                    </div>
                                    <span className="text-sm font-bold text-[var(--color-primary-gold)]">R$ {item.price.toFixed(2)}</span>
                                </div>
                            ))}
                            {completedApps.length === 0 && (
                                <p className="text-gray-500 text-sm italic py-4 px-2">Nenhum serviço finalizado ainda. Agende seu primeiro corte!</p>
                            )}
                        </div>
                    </div>
                </div>

                {promotions.filter((p: any) => p.active).length > 0 && (
                    <div className="space-y-4">
                        <h4 className="px-2 flex items-center gap-2 text-lg font-bold">
                            <TicketPercent className="w-5 h-5 text-[var(--color-primary-gold)]" /> Promoções
                        </h4>
                        {promotions.filter((p: any) => p.active).slice(0, 1).map((promo: any, i: number) => (
                            <Link href="/client/promotions" key={i}>
                                <div className={`group relative overflow-hidden p-6 bg-gradient-to-br ${promo.color} border border-white/5 rounded-3xl hover:scale-[1.02] transition-transform cursor-pointer`}>
                                    <div className="relative z-10">
                                        <span className={`inline-block px-3 py-1 ${promo.accentBg} ${promo.textColor} text-[9px] font-black uppercase rounded-full mb-4`}>{promo.tag}</span>
                                        <h5 className="text-xl font-bold mb-1">{promo.title}</h5>
                                        <p className="text-gray-400 text-xs mb-4 line-clamp-1">{promo.description}</p>
                                        <p className="text-3xl font-black text-[var(--color-primary-gold)] mb-1">R$ {promo.price.toFixed(2)}</p>
                                    </div>
                                </div>
                            </Link>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}
